CREATE TABLE node_votes (
    id        UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    node_id   UUID NOT NULL REFERENCES nodes(id) ON DELETE CASCADE,
    user_id   UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    weight    SMALLINT NOT NULL,
    voted_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT node_votes_weight_check CHECK (weight IN (-1, 1)),
    CONSTRAINT node_votes_unique UNIQUE (node_id, user_id)
);

CREATE INDEX idx_node_votes_node ON node_votes(node_id);
CREATE INDEX idx_node_votes_user ON node_votes(user_id);
